changeSet.sql:
ALTER TABLE staff_invitations
    ADD COLUMN approval_required boolean NOT NULL DEFAULT false,
    ADD COLUMN approved_at       timestamp(6) with time zone,
    ADD COLUMN approved_by       uuid REFERENCES users (id),
    ADD COLUMN rejected_at       timestamp(6) with time zone,
    ADD COLUMN rejected_by       uuid REFERENCES users (id),
    ADD COLUMN rejection_reason  varchar(500);
ALTER TABLE staff_invitations ALTER COLUMN token_hash DROP NOT NULL;
ALTER TABLE staff_invitations ALTER COLUMN last_sent_at DROP NOT NULL;

ALTER TABLE staff_invitations DROP CONSTRAINT chk_staff_invitations_one_outcome;
ALTER TABLE staff_invitations ADD CONSTRAINT chk_staff_invitations_one_outcome
    CHECK (num_nonnulls(accepted_at, revoked_at, rejected_at) <= 1);
ALTER TABLE staff_invitations ADD CONSTRAINT chk_staff_invitations_link_only_when_approved
    CHECK ((token_hash IS NOT NULL) = (NOT approval_required OR approved_at IS NOT NULL));
ALTER TABLE staff_invitations ADD CONSTRAINT chk_staff_invitations_approval
    CHECK (approved_at IS NULL OR (approval_required AND approved_by IS NOT NULL));
ALTER TABLE staff_invitations ADD CONSTRAINT chk_staff_invitations_rejection
    CHECK (rejected_at IS NULL OR (approval_required AND approved_at IS NULL
           AND rejected_by IS NOT NULL AND rejection_reason IS NOT NULL));

DROP INDEX uq_staff_invitations_open_email;
CREATE UNIQUE INDEX uq_staff_invitations_open_email
    ON staff_invitations (tenant_id, lower(email))
    WHERE accepted_at IS NULL AND revoked_at IS NULL AND rejected_at IS NULL AND deleted = false;

COMMENT ON COLUMN staff_invitations.approval_required IS
    'True when a branch manager requested this invitation: no link exists (token_hash null) until a company-wide approver approves it.';

changeSet.rollback:
-- Requests that were never approved have no token and can't survive
-- the restored NOT NULL; they are dropped.
DELETE FROM staff_invitations WHERE token_hash IS NULL;
DROP INDEX uq_staff_invitations_open_email;
CREATE UNIQUE INDEX uq_staff_invitations_open_email
    ON staff_invitations (tenant_id, lower(email))
    WHERE accepted_at IS NULL AND revoked_at IS NULL AND deleted = false;
ALTER TABLE staff_invitations DROP CONSTRAINT chk_staff_invitations_rejection;
ALTER TABLE staff_invitations DROP CONSTRAINT chk_staff_invitations_approval;
ALTER TABLE staff_invitations DROP CONSTRAINT chk_staff_invitations_link_only_when_approved;
ALTER TABLE staff_invitations DROP CONSTRAINT chk_staff_invitations_one_outcome;
ALTER TABLE staff_invitations ADD CONSTRAINT chk_staff_invitations_one_outcome
    CHECK (accepted_at IS NULL OR revoked_at IS NULL);
ALTER TABLE staff_invitations ALTER COLUMN last_sent_at SET NOT NULL;
ALTER TABLE staff_invitations ALTER COLUMN token_hash SET NOT NULL;
ALTER TABLE staff_invitations
    DROP COLUMN rejection_reason, DROP COLUMN rejected_by, DROP COLUMN rejected_at,
    DROP COLUMN approved_by, DROP COLUMN approved_at, DROP COLUMN approval_required;
